namespace {
uint64_t P(std::vector<uint64_t> values,size_t p){std::ranges::sort(values);return values[(values.size()-1)*p/100];}
int64_t SignedP(std::vector<int64_t> values,size_t p){std::ranges::sort(values);return values[(values.size()-1)*p/100];}
uint64_t Mad(const std::vector<uint64_t>& values){const uint64_t median=P(values,50);std::vector<uint64_t> deviations;deviations.reserve(values.size());for(uint64_t value:values)deviations.push_back(value>median?value-median:median-value);return P(std::move(deviations),50);}
DrawList Scene(MeshHandle3D wall,MeshHandle3D mesh,bool hidden){DrawList d;Camera3D camera{{0,0,-8},{0,0,0},{0,1,0},{}};d.SetViewProjection(CreateViewProjectionMatrix(camera,1920.f/1080.f));d.MeshInstance(wall,CreateScaleMatrix({12,8,.2f}),{1,1,1,1},{},MeshRenderLayer3D::Opaque,{},.25f,false,MaterialClass3D::Surface,std::numeric_limits<float>::quiet_NaN(),false);for(size_t i=0;i<4096;++i){const float x=float(int(i%64)-32)*.12f,y=float(int(i/64)-32)*.12f;d.MeshInstance(mesh,CreateTranslationMatrix({x,y,hidden?2.f:-2.f})*CreateScaleMatrix({.08f,.08f,.08f}),{1,1,1,1},{},MeshRenderLayer3D::Opaque,{},.25f,false,MaterialClass3D::Surface,std::numeric_limits<float>::quiet_NaN(),false);}d.SetStaticMeshSubmission3D(d.FreezeMeshInstances3D());return d;}
uint64_t Sample(D3D12Renderer& r,const DrawList& d){const auto b=std::chrono::steady_clock::now();r.Render(d,{.04f,.06f,.09f,1});r.WaitIdle();return uint64_t(std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::steady_clock::now()-b).count());}
struct IsolatedDistribution {std::vector<uint64_t> total,prepass,build,cull,color;};
IsolatedDistribution Isolated(D3D12Renderer& renderer,const DrawList& draw,const char* name){for(size_t index=0;index<16;++index)Sample(renderer,draw);IsolatedDistribution result;for(size_t index=0;index<1000;++index){Sample(renderer,draw);const RendererStats stats=renderer.GetStats();result.total.push_back(stats.lastGpuFrameNanoseconds);result.prepass.push_back(stats.lastHzbPrepassGpuNanoseconds);result.build.push_back(stats.lastHzbBuildGpuNanoseconds);result.cull.push_back(stats.lastHzbCullGpuNanoseconds);result.color.push_back(stats.lastHzbColorGpuNanoseconds);}std::cout<<name<<"_isolated="<<P(result.total,50)<<'/'<<P(result.total,95)<<'/'<<P(result.total,99)<<'/'<<P(result.total,100)<<" pre="<<P(result.prepass,50)<<'/'<<P(result.prepass,95)<<'/'<<P(result.prepass,99)<<'/'<<P(result.prepass,100)<<" build="<<P(result.build,50)<<'/'<<P(result.build,95)<<'/'<<P(result.build,99)<<'/'<<P(result.build,100)<<" cull="<<P(result.cull,50)<<'/'<<P(result.cull,95)<<'/'<<P(result.cull,99)<<'/'<<P(result.cull,100)<<" color="<<P(result.color,50)<<'/'<<P(result.color,95)<<'/'<<P(result.color,99)<<'/'<<P(result.color,100)<<'\n';return result;}
